#!/usr/bin/env node
/* Concatenates src/terms/*.js into assets/js/terms.js and checks the data.
   Run: node scripts/build.js */
const fs = require("fs");
const path = require("path");
const root = path.join(__dirname, "..");
const dir = path.join(root, "src", "terms");
const files = fs.readdirSync(dir).filter((f) => f.endsWith(".js")).sort();

const header =
  "/* Lumenary term data. Generated by scripts/build.js from src/terms/ — edit those files, not this one. */\n" +
  "window.LUMENARY = { terms: [], add: function (list) { Array.prototype.push.apply(this.terms, list); } };\n";
const body = files.map((f) => fs.readFileSync(path.join(dir, f), "utf8").trim()).join("\n");
const out = header + body + "\n";

// Validate: evaluate in a sandbox-like scope
const terms = [];
const LUMENARY = { add: (l) => terms.push(...l) };
new Function("LUMENARY", body)(LUMENARY);
const names = new Set(terms.map((t) => t.t.toLowerCase()));
const problems = [];
const seen = new Set();
const cats = ["exposure", "light", "optics", "composition", "colour", "digital", "gear", "film", "genre", "business"];
for (const t of terms) {
  if (seen.has(t.t.toLowerCase())) problems.push(`duplicate headword: ${t.t}`);
  seen.add(t.t.toLowerCase());
  for (const k of ["t", "pos", "c", "s", "se", "a", "ae"]) if (!t[k]) problems.push(`${t.t}: missing ${k}`);
  if (!cats.includes(t.c)) problems.push(`${t.t}: unknown category ${t.c}`);
  for (const r of t.r || []) if (!names.has(r.toLowerCase())) problems.push(`${t.t}: see-also "${r}" has no entry`);
}
if (problems.length) {
  console.error(problems.join("\n"));
  process.exit(1);
}
fs.writeFileSync(path.join(root, "assets", "js", "terms.js"), out);
console.log(`Built assets/js/terms.js with ${terms.length} terms from ${files.length} files.`);
